    dorsal: [0.3, 0.62],
    secondDorsal: [0, 0],
    eye: [0.06, 0.09],
    gills: [0.13, 0.17],
    tint: [1, 1, 1],
    tail: { kind: "caudal", length: 0.24, width: 0.07, twist: 0.06 },
