      if (s < 0.84) return 0.125 - 0.097 * Math.pow((s - 0.3) / 0.54, 1.2);
      return 0.028 - 0.008 * smoothstep(0.84, 1, s);
    },
    pectoral: [0.14, 0.24, 0.32, 0.2],
    paddle: true,
    falcate: false,
    pelvic: [0, 0, 0, 0],
    caudal: 0,
    dorsal: [0.36, 0.45],
    secondDorsal: [0, 0],
    eye: [0.1, 0.12],
    gills: [0, 0],
    tint: [1, 1, 1],
    tail: { kind: "fluke", span: 0.14, length: 0.17, notch: 0.03 },
    undulation: 0.15,
    finFlap: 0.03,
  },
  coats: { orca: orcaCoat },
  defaultCoat: "orca",
