import type { SharkKind } from "../world";

/** Every animal the sim and renderer know how to draw. Later rounds extend this union. */
export type CreatureSpecies = SharkKind | "koi" | "bottlenose" | "orca" | "humpback";

/** Which animals to put in the water. `size` is an extra multiplier on the real-size scaling. */
export type CreatureGroup = {
  species: CreatureSpecies;
  /** How many of this species, 1–12. Default 1. */
  count?: number;
  /** Extra size multiplier on top of the species' real-size scaling. Default 1. */
  size?: number;
  /** Coat to use, or a list to pick from per animal (koi: kohaku, sanke, showa, tancho, ogon, asagi). Ignored by species without coats. */
  variety?: string | string[];
};

/** `ocean` is the open sea; `pond` is a bait-free tank, so baitFish defaults to off. */
export type OceanScene = "ocean" | "pond";

/** `stylized` compresses the size gap between species; `true` keeps real length ratios. */
export type OceanScale = "stylized" | "true";

/** What a pointer press does to the water. */
export type OceanInteraction =
  /** A press drops food: nearby animals swim over to eat, each in its own way. */
  | "feed"
  /** A press flashes the water. */
  | "splash"
  /** Presses are ignored. */
  | "none";

/** OKLCH colour: lightness 0–1, chroma, hue in degrees. */
export type Oklch = [number, number, number];

/** Koi colour varieties; each one is a coat on the koi species. */
export type KoiVariety = "kohaku" | "sanke" | "showa" | "tancho" | "ogon" | "asagi";

/** Where on the body a point is, for painting: s along (0 snout → 1 tail), v across in px (signed), L the body length, across 0 (spine) → 1 (edge of the body), flag the renderer's cell flag (body, fin, ridge, eye...). */
export type PaintPoint = {
  s: number;
  v: number;
  L: number;
  across: number;
  flag: number;
  id: number;
  /** The animal has rolled far enough to show its underside (orca belly, a shark's pale ventral side). */
  belly: boolean;
  /** How far the underside shows, 0 (none) → 1 (fully rolled), eased across the roll so a belly grows in. `belly` is `bellyAmount > 0.5`. */
  bellyAmount: number;
};

/** Natural colours: `regions[0]` is the base skin; `paint` returns a region index for a point. */
export interface Coat {
  regions: readonly Oklch[];
  paint?: (p: PaintPoint) => number;
  /** Sparkle the scale glyphs in pale gold and white instead of the accent colours (ogon). */
  glint?: boolean;
}

/** `natural` paints animals in their real colours on any theme; `theme` keeps them greyscale. */
export type OceanColors = "natural" | "theme";

/** Tail drawn instead of the shark's forked caudal fin. */
export type TailShape =
  /** Whale/dolphin flukes: a horizontal, swept-back wing. From `1 - length` to the tail tip; the tips reach the end, the centre notch sits `notch` before it. */
  | { kind: "fluke"; span: number; length: number; notch: number }
  /** A fish's vertical caudal fin seen from above: a narrow blade behind the peduncle. `width` is its half-width at the tip at rest, `twist` the extra half-width at the peak of a beat, both fractions of length. */
  | { kind: "caudal"; length: number; width: number; twist: number };

/** Body outline and fin layout per species. All values are fractions of length. */
export interface BodyShape {
  halfWidth: (s: number) => number;
  /** Pectoral fin: leading root, trailing root, tip position along the body, and reach. */
  pectoral: [number, number, number, number];
  /** Notched (falcate) trailing edge on the pectorals. */
  falcate: boolean;
  /** Rounded paddle pectorals (koi, orca) instead of the triangle; `falcate` is ignored. */
  paddle?: boolean;
  /** Pelvic fins: leading root, trailing root, tip, reach. */
  pelvic: [number, number, number, number];
  /** Forked caudal fin reach, or 0 when the tail is a ribbon (zebra shark). */
  caudal: number;
  dorsal: [number, number];
  secondDorsal: [number, number];
  /**
   * Hammerheads' cephalofoil: half-span, how far its tips sweep back, its depth, and the
   * notch in the middle of the front edge. All fractions of length; absent for other sharks.
   */
  head?: { span: number; sweep: number; depth: number; notch: number };
  /** null when the eyes sit somewhere else (hammerhead: on the cephalofoil tips). */
  eye: [number, number] | null;
  gills: [number, number];
  /** Skin colour multipliers (r, g, b). */
  tint: [number, number, number];
  /** Tail drawn instead of the shark's forked caudal fin. */
  tail?: TailShape;
  /** Multiplies the side-to-side body wave. Default 1. Whales and dolphins beat their tails up and down, so from above they barely bend; use about 0.15 for them. */
  undulation?: number;
  /** Pectoral flex amplitude. Default 0.06. */
  finFlap?: number;
  /** Pectoral flex frequency as a multiple of the tail-beat phase. Default 0.5. */
  finFlapRate?: number;
}

export interface CreatureDef {
  /** Typical adult length in metres. Sets the size ratios between species. */
  realLength: number;
  shape: BodyShape;
  /** Dark skin markings at body point (s along, v across); `id` seeds per-animal patterns. */
  marking?: (s: number, v: number, L: number, across: number, id: number) => boolean;
  /** Pale ridges along the back (zebra shark). */
  paleRidge?: (s: number, across: number) => boolean;
  /** Named natural colour schemes (koi varieties). Sharks leave it out and keep their tinted greys. */
  coats?: Record<string, Coat>;
  /** Coat used when a group gives no variety. */
  defaultCoat?: string;
}

import { clamp, hash3 } from "./math";

/** 0 spray, 1 bubble, 2 blow mist. */
export type ParticleKind = 0 | 1 | 2;

const KIND_SPRAY: ParticleKind = 0;
const KIND_BUBBLE: ParticleKind = 1;
const KIND_MIST: ParticleKind = 2;

/** Spray decelerates as v *= exp(-SPRAY_DRAG * dt). */
const SPRAY_DRAG = 3;
/** Blow mist slows more gently, so the cloud keeps spreading for its whole life. */
const MIST_DRAG = 1;
const MIST_LIFE = 2.4;
/** The plume leans downwind: a constant drift of (0.35, −0.12) plume radii per second, not slowed by drag. */
const MIST_WIND_X = 0.35;
const MIST_WIND_Y = -0.12;
const BUBBLE_SPEED = 4;

/**
 * Render-side particles and surface rings. Struct-of-arrays in fixed pools: a full pool
 * overwrites its oldest slot, and nothing is allocated after construction.
 * Effects knows nothing about canvas; the renderer draws what forEach* visits.
 *
 * Randomness comes only from hash3 on the caller's seed, so the same events give the same effects.
 */
export class Effects {
  private readonly maxParticles: number;
  private readonly maxRings: number;

  private px: Float32Array;
  private py: Float32Array;
  private pvx: Float32Array;
  private pvy: Float32Array;
  /** Constant drift per particle (mist only), not damped by drag. */
  private pwx: Float32Array;
  private pwy: Float32Array;
  private page: Float32Array;
  private plife: Float32Array;
  private pkind: Uint8Array;
  private palive: Uint8Array;
  private pnext = 0;

  private rx: Float32Array;
  private ry: Float32Array;
  private rr: Float32Array;
  private rspeed: Float32Array;
  private rmax: Float32Array;
  private rstrength: Float32Array;
  /** Seconds left before a ring starts to grow; it is alive but not drawn until this reaches 0. */
  private rdelay: Float32Array;
  private ralive: Uint8Array;
  /** Per ring: a seed fixed at spawn (its shape), and the seconds since it spawned. */
  private rseed: Float32Array;
  private rage: Float32Array;
  private rnext = 0;
  private rcount = 0;

  constructor(maxParticles = 400, maxRings = 64) {
    this.maxParticles = maxParticles;
    this.maxRings = maxRings;
    this.px = new Float32Array(maxParticles);
    this.py = new Float32Array(maxParticles);
    this.pvx = new Float32Array(maxParticles);
    this.pvy = new Float32Array(maxParticles);
    this.pwx = new Float32Array(maxParticles);
    this.pwy = new Float32Array(maxParticles);
    this.page = new Float32Array(maxParticles);
    this.plife = new Float32Array(maxParticles);
    this.pkind = new Uint8Array(maxParticles);
    this.palive = new Uint8Array(maxParticles);
    this.rx = new Float32Array(maxRings);
    this.ry = new Float32Array(maxRings);
    this.rr = new Float32Array(maxRings);
    this.rspeed = new Float32Array(maxRings);
    this.rmax = new Float32Array(maxRings);
    this.rstrength = new Float32Array(maxRings);
    this.rdelay = new Float32Array(maxRings);
    this.ralive = new Uint8Array(maxRings);
    this.rseed = new Float32Array(maxRings);
    this.rage = new Float32Array(maxRings);
  }

  /**
   * Expanding ring on the surface: radius grows at `speed` px/s until `maxR`, fading.
   * With `delay` > 0 the ring waits that many seconds, invisible, before it starts to grow.
   */
  ring(x: number, y: number, speed: number, maxR: number, strength: number, delay = 0) {
    const i = this.rnext;
    this.rnext = (i + 1) % this.maxRings;
    this.rx[i] = x;
    this.ry[i] = y;
    this.rr[i] = 0;
    this.rspeed[i] = speed;
    this.rmax[i] = maxR;
    this.rstrength[i] = strength;
    this.rdelay[i] = delay;
    this.ralive[i] = 1;
    this.rage[i] = 0;
    this.rseed[i] = hash3(this.rcount++, i, 90);
  }

  /** `n` spray droplets thrown outward from (x, y) up to `reach` px. */
  spray(x: number, y: number, n: number, reach: number, seed: number) {
    for (let k = 0; k < n; k++) {
      const angle = hash3(seed, k, 1) * Math.PI * 2;
      // Under exponential drag the droplet travels v0 / SPRAY_DRAG in total, so v0 sets the reach.
      const v0 = SPRAY_DRAG * reach * (0.4 + 0.6 * hash3(seed, k, 2));
      const i = this.claim(x, y, KIND_SPRAY, 0.6 + 0.4 * hash3(seed, k, 3));
      this.pvx[i] = Math.cos(angle) * v0;
      this.pvy[i] = Math.sin(angle) * v0;
    }
  }

  /** A bubble that rises: shrinks o → ° → . and fades over `life` s, drifting slightly. */
  bubble(x: number, y: number, life: number, seed: number) {
    const i = this.claim(x, y, KIND_BUBBLE, life);
    // Up at 2–4 px/s with a sideways wobble of up to 2 px/s, so the speed stays near BUBBLE_SPEED.
    this.pvx[i] = (hash3(seed, 0, 4) * 2 - 1) * (BUBBLE_SPEED / 2);
    this.pvy[i] = -(BUBBLE_SPEED / 2 + hash3(seed, 0, 5) * (BUBBLE_SPEED / 2));
  }

  /**
   * A blow: a soft cluster of mist, `radius` px across, that spreads, fades slowly and leans downwind. A bigger
   * radius (a bigger animal) gives more particles, from 8 up to 28.
   */
  blow(x: number, y: number, radius: number, seed: number) {
    const n = Math.round(clamp(radius / 6, 8, 28));
    for (let k = 0; k < n; k++) {
      const angle = hash3(seed, k, 6) * Math.PI * 2;
      const r0 = radius * Math.sqrt(hash3(seed, k, 7));
      const i = this.claim(
        x + Math.cos(angle) * r0,
        y + Math.sin(angle) * r0,
        KIND_MIST,
        MIST_LIFE,
      );
      // Radial speed that carries the cloud out to about `radius` under MIST_DRAG.
      const v0 = MIST_DRAG * radius * (0.5 + 0.5 * hash3(seed, k, 8));
      this.pvx[i] = Math.cos(angle) * v0;
      this.pvy[i] = Math.sin(angle) * v0;
      this.pwx[i] = MIST_WIND_X * radius;
      this.pwy[i] = MIST_WIND_Y * radius;
    }
  }

  step(dt: number) {
    const { palive, page, plife, px, py, pvx, pvy, pwx, pwy, pkind } = this;
    const spray = Math.exp(-SPRAY_DRAG * dt);
    const mist = Math.exp(-MIST_DRAG * dt);
    for (let i = 0; i < this.maxParticles; i++) {
      if (!palive[i]) continue;
      page[i] += dt;
      if (page[i] >= plife[i]) {
        palive[i] = 0;
        continue;
      }
      const kind = pkind[i];
      if (kind === KIND_SPRAY) {
        pvx[i] *= spray;
        pvy[i] *= spray;
      } else if (kind === KIND_MIST) {
        pvx[i] *= mist;
        pvy[i] *= mist;
      }
      px[i] += (pvx[i] + pwx[i]) * dt;
      py[i] += (pvy[i] + pwy[i]) * dt;
    }
    const { ralive, rr, rspeed, rmax, rdelay, rage } = this;
    for (let i = 0; i < this.maxRings; i++) {
      if (!ralive[i]) continue;
      rage[i] += dt;
      let t = dt;
      if (rdelay[i] > 0) {
        if (rdelay[i] >= t) {
          rdelay[i] -= t;
          continue;
        }
        // The wait ends partway through this step; the rest of the step is growth.
        t -= rdelay[i];
        rdelay[i] = 0;
      }
      rr[i] += rspeed[i] * t;
      if (rr[i] >= rmax[i]) ralive[i] = 0;
    }
  }

  /** Visit live particles and rings. The renderer draws them; Effects knows nothing about canvas. */
  forEachParticle(fn: (x: number, y: number, kind: ParticleKind, age01: number) => void) {
    for (let i = 0; i < this.maxParticles; i++) {
      if (!this.palive[i]) continue;
      fn(this.px[i], this.py[i], this.pkind[i] as ParticleKind, this.page[i] / this.plife[i]);
    }
  }

  /** Visits the rings that are growing. `seed` fixes the ring's shape; `age` is seconds since it spawned. */
  forEachRing(
    fn: (x: number, y: number, r: number, alpha: number, seed: number, age: number) => void,
  ) {
    for (let i = 0; i < this.maxRings; i++) {
      if (!this.ralive[i] || this.rdelay[i] > 0) continue;
      const fade = 1 - this.rr[i] / this.rmax[i];
      fn(this.rx[i], this.ry[i], this.rr[i], this.rstrength[i] * fade, this.rseed[i], this.rage[i]);
    }
  }

  /** Takes the next slot (the oldest once the pool is full) and starts a particle there. */
  private claim(x: number, y: number, kind: ParticleKind, life: number) {
    const i = this.pnext;
    this.pnext = (i + 1) % this.maxParticles;
    this.px[i] = x;
    this.py[i] = y;
    this.pvx[i] = 0;
    this.pvy[i] = 0;
    this.pwx[i] = 0;
    this.pwy[i] = 0;
    this.page[i] = 0;
    this.plife[i] = life;
    this.pkind[i] = kind;
    this.palive[i] = 1;
    return i;
  }
}

// Ported from https://github.com/stackedlol/ascii-sharks (used with the author's permission).
import { createPaletteReader } from "./palette";
import { AsciiRenderer, type OceanPalette } from "./renderer";
import type { RosterEntry } from "./creatures/roster";
import type { OceanColors, OceanInteraction, OceanScene } from "./creatures/types";
import { World } from "./world";

const STEP = 1 / 60;
const MAX_STEPS = 4;
/** A press is a click only if the pointer moved less than this many px, within this many ms. */
const CLICK_PX = 6;
const CLICK_MS = 500;
/** Presses on these are for the page (links, buttons, inputs), not for the ocean. */
const INTERACTIVE = "a, button, input, textarea, select, label, [role=button], [contenteditable]";

/** Constructor options for OceanEngine: the world's setup plus the pointer behaviour. */
export type EngineOptions = {
  roster?: RosterEntry[];
  seed?: number;
  scene?: OceanScene;
  baitFish?: number | "auto" | false;
  /** "feed" drops food on a click; "splash" flashes the water on press; "none" ignores presses. Hover avoidance is always on. */
  interaction?: OceanInteraction;
  /** Animal colouring: real colours ("natural") or greyscale that inverts on light pages ("theme"). Default "theme". */
  colors?: OceanColors;
  /** Sea surface (swell, sun glitter, wind streaks) and wakes (natural colours only). Turn off for a calmer background. Default true. */
  surface?: boolean;
};

/**
 * Wires World + AsciiRenderer to a canvas: variable-substep loop, resize,
 * pointer input, pausing off-screen, and prefers-reduced-motion.
 */
export class OceanEngine {
  private world: World;
  private renderer: AsciiRenderer;
  private raf = 0;
  private last = 0;
  private visible = true;
  private reducedMotion: MediaQueryList;
  private colorScheme: MediaQueryList;
  private themeObserver: MutationObserver;
  private resizeObserver: ResizeObserver;
  private intersectionObserver: IntersectionObserver;
  private disposed = false;
  private readPalette: (el: HTMLElement) => OceanPalette;
  private canvas: HTMLCanvasElement;
  private interaction: OceanInteraction;
  /** Where the current feed press started, or null. */
  private press: { x: number; y: number; t: number } | null = null;

  constructor(canvas: HTMLCanvasElement, options: EngineOptions) {
    this.canvas = canvas;
    this.readPalette = createPaletteReader();
    this.interaction = options.interaction ?? "splash";
    this.world = new World({
      roster: options.roster,
      seed: options.seed,
      scene: options.scene,
      baitFish: options.baitFish,
    });
    this.renderer = new AsciiRenderer(canvas);
    this.renderer.setColors(options.colors ?? "theme");
    this.renderer.setSurface(options.surface ?? true);
    this.renderer.setScene(options.scene ?? "ocean", options.seed ?? 0);
    this.renderer.setFontFamily(getComputedStyle(canvas).fontFamily);
    this.renderer.setPalette(this.readPalette(this.canvas));
    this.reducedMotion = window.matchMedia("(prefers-reduced-motion: reduce)");
    this.colorScheme = window.matchMedia("(prefers-color-scheme: dark)");
    this.colorScheme.addEventListener("change", this.onThemeChange);
    this.themeObserver = new MutationObserver(this.onThemeChange);
    this.themeObserver.observe(document.documentElement, {
      attributes: true,
      attributeFilter: ["class", "style", "data-theme"],
    });

    this.resizeObserver = new ResizeObserver(() => this.resize());
    this.resizeObserver.observe(canvas);
    this.intersectionObserver = new IntersectionObserver(([entry]) => {
      this.visible = entry.isIntersecting;
      this.schedule();
    });
    this.intersectionObserver.observe(canvas);

    this.reducedMotion.addEventListener("change", this.onMotionPreference);
    window.addEventListener("pointermove", this.onPointerMove, { passive: true });
    window.addEventListener("pointerdown", this.onPointerDown, { passive: true });
    window.addEventListener("pointerup", this.onPointerUp, { passive: true });
    window.addEventListener("pointercancel", this.onPointerCancel, { passive: true });
    document.documentElement.addEventListener("pointerleave", this.onPointerLeave);
    window.addEventListener("blur", this.onPointerLeave);

    this.resize();
    // Canvas text can't trigger a webfont load; once the mono face is in, redraw.
    document.fonts?.load(`600 16px ${getComputedStyle(canvas).fontFamily}`).then(() => {
      if (!this.disposed && this.reducedMotion.matches) this.drawStill();
    });
    this.schedule();
  }

  destroy() {
    this.disposed = true;
    cancelAnimationFrame(this.raf);
    this.resizeObserver.disconnect();
    this.intersectionObserver.disconnect();
    this.themeObserver.disconnect();
    this.colorScheme.removeEventListener("change", this.onThemeChange);
    this.reducedMotion.removeEventListener("change", this.onMotionPreference);
    window.removeEventListener("pointermove", this.onPointerMove);
    window.removeEventListener("pointerdown", this.onPointerDown);
    window.removeEventListener("pointerup", this.onPointerUp);
    window.removeEventListener("pointercancel", this.onPointerCancel);
    document.documentElement.removeEventListener("pointerleave", this.onPointerLeave);
    window.removeEventListener("blur", this.onPointerLeave);
  }

  /** Starts a random jumper's jump (see World.playRandomJump). Reduced motion has no shows, so it returns 0. */
  playRandomJump(): number {
    if (this.reducedMotion.matches) return 0;
    return this.world.playRandomJump();
  }

  hasJumpers(): boolean {
    return this.world.hasJumpers();
  }

  private resize() {
    // Layout size, not getBoundingClientRect(): a CSS transform on an ancestor
    // (e.g. a scaled preview) must not shrink the world.
    const width = this.canvas.clientWidth;
    const height = this.canvas.clientHeight;
    if (width < 1 || height < 1) return;
    const dpr = Math.min(window.devicePixelRatio || 1, 2);
    this.renderer.resize(width, height, dpr);
    this.world.resize(width, height, this.renderer.cellWidth, this.renderer.cellHeight);
    if (this.reducedMotion.matches) this.drawStill();
  }

  private schedule() {
    cancelAnimationFrame(this.raf);
    if (this.disposed || !this.visible || this.reducedMotion.matches) return;
    this.last = performance.now();
    this.raf = requestAnimationFrame(this.frame);
  }

  private frame = (now: number) => {
    const dt = Math.min(0.1, (now - this.last) / 1000);
    this.last = now;
    // Variable substeps: n equal steps that add up to this frame's dt, so motion does not judder at 120 or 144 Hz.
    // A non-positive dt (a timestamp from before the last schedule) steps nothing; the world divides by dt.
    if (dt > 0) {
      const n = Math.min(MAX_STEPS, Math.max(1, Math.ceil(dt / STEP)));
      for (let i = 0; i < n; i++) this.world.step(dt / n);
    }
    this.renderer.render(this.world, Math.max(0, dt));
    this.raf = requestAnimationFrame(this.frame);
  };

  /** Reduced motion: let the ecosystem settle, then show a single frame. */
  private drawStill() {
    if (this.world.time < 4) {
      for (let i = 0; i < 240; i++) this.world.step(STEP);
    }
    this.renderer.render(this.world, STEP);
  }

  private onMotionPreference = () => {
    if (this.reducedMotion.matches) {
      cancelAnimationFrame(this.raf);
      this.drawStill();
    } else {
      this.schedule();
    }
  };

  /** Light/dark switch or accent change: re-read the page colours and repaint. */
  private onThemeChange = () => {
    this.renderer.setPalette(this.readPalette(this.canvas));
    if (this.reducedMotion.matches) this.drawStill();
  };

  private toLocal(e: PointerEvent) {
    const rect = this.canvas.getBoundingClientRect();
    // Map screen pixels back to layout pixels when an ancestor is transformed.
    const sx = rect.width > 0 ? this.canvas.clientWidth / rect.width : 1;
    const sy = rect.height > 0 ? this.canvas.clientHeight / rect.height : 1;
    const x = (e.clientX - rect.left) * sx;
    const y = (e.clientY - rect.top) * sy;
    const inside =
      x >= 0 && y >= 0 && x <= this.canvas.clientWidth && y <= this.canvas.clientHeight;
    return { x, y, inside };
  }

  private onPointerMove = (e: PointerEvent) => {
    const { x, y, inside } = this.toLocal(e);
    const p = this.world.pointer;
    p.x = x;
    p.y = y;
    p.active = inside && e.pointerType !== "touch";
  };

  private onPointerDown = (e: PointerEvent) => {
    if (this.interaction === "none") return;
    const { x, y, inside } = this.toLocal(e);
    if (this.interaction === "feed") {
      // Only a primary-button press (or a touch or pen tap) can feed.
      if (e.button !== 0) {
        this.press = null;
        return;
      }
      const onControl = (e.target as Element | null)?.closest?.(INTERACTIVE);
      this.press = inside && !onControl ? { x, y, t: performance.now() } : null;
      return;
    }
    if (inside && !this.reducedMotion.matches) this.world.splash(x, y);
  };

  /** A scroll or other gesture took the pointer over, so the press is not a click. */
  private onPointerCancel = () => {
    this.press = null;
  };

  /** Feed mode: a press and release close together, in place, is a click that drops food. */
  private onPointerUp = (e: PointerEvent) => {
    const press = this.press;
    this.press = null;
    if (!press || this.interaction !== "feed" || this.reducedMotion.matches) return;
    const { x, y, inside } = this.toLocal(e);
    const moved = Math.hypot(x - press.x, y - press.y);
    if (!inside || moved > CLICK_PX || performance.now() - press.t > CLICK_MS) return;
    this.world.offerFood(press.x, press.y);
  };

  private onPointerLeave = () => {
    this.world.pointer.active = false;
  };
}

// Ported from https://github.com/stackedlol/ascii-sharks (used with the author's permission).
export const TAU = Math.PI * 2;

export const clamp = (v: number, lo: number, hi: number) => (v < lo ? lo : v > hi ? hi : v);

/** Uniform random source, returning values in [0, 1). */
export type Rng = () => number;

/** Seeded 32-bit PRNG (mulberry32): the same seed always yields the same sequence. */
export function createRng(seed: number): Rng {
  let s = seed >>> 0;
  return () => {
    s = (s + 0x6d2b79f5) >>> 0;
    let t = s;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

export const rand = (rng: Rng, lo: number, hi: number) => lo + rng() * (hi - lo);

export const randInt = (rng: Rng, lo: number, hi: number) => Math.floor(rand(rng, lo, hi + 1));

export function smoothstep(e0: number, e1: number, x: number) {
  const t = clamp((x - e0) / (e1 - e0), 0, 1);
  return t * t * (3 - 2 * t);
}

/** Shortest signed angle from a to b, in (-PI, PI]. */
export function angleDiff(a: number, b: number) {
  let d = (b - a) % TAU;
  if (d > Math.PI) d -= TAU;
  if (d < -Math.PI) d += TAU;
  return d;
}

/** Cheap integer hash → [0, 1). Deterministic, so textures stay stable. */
export function hash3(x: number, y: number, z: number) {
  let h = Math.imul(x | 0, 374761393) ^ Math.imul(y | 0, 668265263) ^ Math.imul(z | 0, 1442695041);
  h = Math.imul(h ^ (h >>> 13), 1274126177);
  h ^= h >>> 16;
  return (h >>> 0) / 4294967296;
}

const K1 = 1 / 260;
const K2 = 1 / 310;
const K3 = 1 / 190;
const CURRENT_SCALE = 3400;

/**
 * Divergence-free ocean current: the curl of a slowly drifting stream
 * function ψ(x, y, t). Because it has no sources or sinks, it moves the
 * schools around without bunching them up in one corner.
 */
export function current(x: number, y: number, t: number, out: { x: number; y: number }) {
  const a = x * K1 + t * 0.07;
  const b = y * K2 - t * 0.05;
  const c = (x + y) * K3 + t * 0.11;
  // u = ∂ψ/∂y, v = -∂ψ/∂x with ψ = sin(a)cos(b) + 0.5 sin(c)
  out.x = (-K2 * Math.sin(a) * Math.sin(b) + 0.5 * K3 * Math.cos(c)) * CURRENT_SCALE;
  out.y = (-K1 * Math.cos(a) * Math.cos(b) - 0.5 * K3 * Math.cos(c)) * CURRENT_SCALE;
  return out;
}

/** Converts OKLCH (L 0–1, C, H in degrees) to sRGB bytes 0–255, clamped to the gamut. */
export function oklchToRgb(l: number, c: number, h: number): [number, number, number] {
  const rad = (h * Math.PI) / 180;
  const a = c * Math.cos(rad);
  const b = c * Math.sin(rad);
  // OKLab → LMS (cube-rooted), then cube to LMS.
  const l_ = l + 0.3963377774 * a + 0.2158037573 * b;
  const m_ = l - 0.1055613458 * a - 0.0638541728 * b;
  const s_ = l - 0.0894841775 * a - 1.291485548 * b;
  const L3 = l_ * l_ * l_;
  const M3 = m_ * m_ * m_;
  const S3 = s_ * s_ * s_;
  // LMS → linear sRGB.
  const lin = [
    4.0767416621 * L3 - 3.3077115913 * M3 + 0.2309699292 * S3,
    -1.2684380046 * L3 + 2.6097574011 * M3 - 0.3413193965 * S3,
    -0.0041960863 * L3 - 0.7034186147 * M3 + 1.707614701 * S3,
  ];
  // Linear → gamma-encoded sRGB, then bytes.
  const encode = (x: number) =>
    Math.round(
      clamp((x <= 0.0031308 ? 12.92 * x : 1.055 * Math.pow(x, 1 / 2.4) - 0.055) * 255, 0, 255),
    );
  return [encode(lin[0]), encode(lin[1]), encode(lin[2])];
}

/** OKLab lightness (0–1) of an sRGB colour given as bytes 0–255: the inverse of the lightness path in oklchToRgb. */
export function rgbToOklabL(r: number, g: number, b: number): number {
  const lin = (c: number) => {
    const x = c / 255;
    return x <= 0.04045 ? x / 12.92 : Math.pow((x + 0.055) / 1.055, 2.4);
  };
  const R = lin(r);
  const G = lin(g);
  const B = lin(b);
  // Linear sRGB → LMS, cube root, then the lightness row of the OKLab matrix.
  const l = Math.cbrt(0.4122214708 * R + 0.5363325363 * G + 0.0514459929 * B);
  const m = Math.cbrt(0.2119034982 * R + 0.6806995451 * G + 0.1073969566 * B);
  const s = Math.cbrt(0.0883024619 * R + 0.2817188376 * G + 0.6299787005 * B);
  return 0.2104542553 * l + 0.793617785 * m - 0.0040720468 * s;
}

import { DEFAULT_PALETTE, type OceanPalette } from "./renderer";

/**
 * Returns a reader that takes the page colours from an element's `background-color` and `color`.
 * It keeps one probe canvas, created on first use, to resolve any CSS colour (including oklch()).
 */
export function createPaletteReader(): (el: HTMLElement) => OceanPalette {
  let probe: CanvasRenderingContext2D | null = null;

  /** Resolves any CSS colour (including oklch()) to rgba bytes via a reusable 1×1 canvas. */
  const toRgba = (css: string): Uint8ClampedArray | null => {
    if (!probe) {
      const canvas = document.createElement("canvas");
      canvas.width = 1;
      canvas.height = 1;
      probe = canvas.getContext("2d", { willReadFrequently: true });
    }
    const ctx = probe;
    if (!ctx) return null;
    ctx.clearRect(0, 0, 1, 1);
    ctx.fillStyle = "#000";
    ctx.fillStyle = css;
    ctx.fillRect(0, 0, 1, 1);
    return ctx.getImageData(0, 0, 1, 1).data;
  };

  return (el: HTMLElement): OceanPalette => {
    const style = getComputedStyle(el);
    const bg = toRgba(style.backgroundColor);
    const fg = toRgba(style.color);
    // No background colour (transparent): keep the default look.
    if (!bg || !fg || bg[3] === 0) return DEFAULT_PALETTE;
    const luminance = (0.2126 * bg[0] + 0.7152 * bg[1] + 0.0722 * bg[2]) / 255;
    return {
      background: [bg[0], bg[1], bg[2]],
      foreground: [fg[0], fg[1], fg[2]],
      mode: luminance > 0.5 ? "light" : "dark",
    };
  };
}

/**
 * Pond plants: lily pads, water lilies and duckweed floating on still water. Render-side only, so the world rng
 * never sees them. Layout draws from hash3 on a seed made from the canvas size, so the same size gives the same
 * pond. Typed arrays are sized in layout(); step, the pushes and the draw passes allocate nothing.
 */
import { clamp, hash3, oklchToRgb } from "./math";

type OKLCH = [number, number, number];

const SALT = 0x51a7;
const TAU = Math.PI * 2;
/** Pads: one per this many px² of canvas, clamped to PAD_MIN..PAD_MAX. */
const PAD_AREA = 60000;
const PAD_MIN = 6;
const PAD_MAX = 14;
/** Pads' summed disc area is capped at this share of the canvas, so small canvases with big koi stay open. */
const PAD_COVER = 0.08;
/** Pad radius in koi lengths, and the margin a pad keeps from the canvas edge (in radii). */
const PAD_R_MIN = 0.12;
const PAD_R_SPAN = 0.1;
const PAD_MARGIN = 0.5;
const PAD_TRIES = 20;
/** Pads turn at up to this many rad/s. */
const PAD_SPIN = 0.03;
/** Every pad has a 30° V-notch from the centre to the rim: 15° either side of its centreline. */
const NOTCH_COS = Math.cos((15 * Math.PI) / 180);
/** Veins: 7 to 9 spokes at even angles, skipping the notch. A cell is on a spoke within VEIN_HALF cells of it, past VEIN_INNER radii. */
const SPOKES_MIN = 7;
const SPOKES_MAX = 9;
const SPOKE_NOTCH_CLEAR = 0.3;
const VEIN_HALF = 0.5;
const VEIN_INNER = 0.2;
/** Body shading: inner below INNER_EDGE radii, mid below MID_EDGE, outer beyond. Jitter moves a cell one step. */
const INNER_EDGE = 0.4;
const MID_EDGE = 0.75;
/** About one pad in three carries a water lily, 0.3 radii out opposite the notch. 80% of lilies are white. */
const FLOWER_CHANCE = 0.25;
const FLOWER_REACH = 0.3;
const FLOWER_WHITE_CHANCE = 0.8;
/** The lily's 3 by 3 cells: row -1, row 0 (the stamen `@` in the centre), and row +1. */
const FLOWER_ROWS = ["\\|/", "*@*", "/'\\"];
/** Duckweed: 4 to 7 patches of 6 to 16 fronds, each patch 0.06 to 0.14 koi lengths across. */
const PATCH_MIN = 4;
const PATCH_MAX = 7;
const FROND_MIN = 6;
const FROND_MAX = 16;
const PATCH_R_MIN = 0.06;
const PATCH_R_SPAN = 0.08;
/** Loose fronds: 10 to 20 single fronds that drift alone. */
const LOOSE_MIN = 10;
const LOOSE_MAX = 20;
/** Duckweed follows the wind at this multiple of the pad speed. */
const DUCK_SPEED = 1.3;
/** The slow wind drift, px/s: vx = WIND_X sin(RATE t + phase), vy = WIND_Y cos(RATE t + phase). */
const WIND_X = 2.2;
const WIND_X_RATE = 0.05;
const WIND_Y = 1.6;
const WIND_Y_RATE = 0.037;
/** A ripple or eat reaches PUSH_REACH_R radii plus PUSH_REACH_SIZE body lengths, and gives PUSH_SPEED px/s. */
const PUSH_SPEED = 14;
const PUSH_DECAY = 1.5;
const PUSH_REACH_R = 1.4;
const PUSH_REACH_SIZE = 0.4;
/** Pads drift back from the margins: px/s² per px past the margin. */
const EDGE_SPRING = 6;
/** A koi pushes plants aside: they take this share of its velocity, scaled by how deep the overlap is. */
const WAKE_GAIN = 0.6;
/** Pads and patches are never pushed faster than this, px/s. The decay then brings them back to the wind. */
const PAD_MAX_SPEED = 40;
/** Sub-cell sample points (x, y pairs) for pad coverage, as in the renderer. */
const SUB = [0.25, 0.3, 0.75, 0.3, 0.25, 0.72, 0.75, 0.72];
/** Shadow offset from the pad centre, in radii. The shadow falls on the floor. */
const SHADOW_DX = 0.18;
const SHADOW_DY = 0.28;
/** The shadow is black: the darker of black and half the page background is always black. */
const SHADOW_ALPHA = { dark: 0.14, light: 0.08 };
// Plant colours in OKLCH, converted once in setPalette.
const BODY_INNER: OKLCH = [0.41, 0.09, 146];
const BODY_MID: OKLCH = [0.46, 0.1, 142];
const BODY_OUTER: OKLCH = [0.5, 0.105, 140];
const RIM: OKLCH = [0.54, 0.1, 138];
const RIM_INK: OKLCH = [0.38, 0.08, 142];
const VEIN_INK: OKLCH = [0.32, 0.08, 148];
const PETAL_WHITE: OKLCH = [0.96, 0.015, 95];
// White petals would vanish on a white page; there they read as cream with a faint pink blush.
const PETAL_WHITE_LIGHT: OKLCH = [0.78, 0.05, 60];
const PETAL_PINK: OKLCH = [0.82, 0.09, 350];
const STAMEN: OKLCH = [0.85, 0.16, 95];
const DUCK: OKLCH = [0.74, 0.17, 128];
const DUCK_DARK: OKLCH = [0.66, 0.15, 132];

function css(c: OKLCH) {
  const [r, g, b] = oklchToRgb(c[0], c[1], c[2]);
  return `rgb(${r},${g},${b})`;
}

/** Vein glyph for a cell's direction from the pad centre: a dash, a bar, or a slash. */
function veinGlyph(dx: number, dy: number) {
  const ax = Math.abs(dx);
  const ay = Math.abs(dy);
  if (ax > 2.4 * ay) return "-";
  if (ay > 2.4 * ax) return "|";
  return dx * dy > 0 ? "\\" : "/";
}

/** Caps a body's speed at PAD_MAX_SPEED. */
function capSpeed(ax: Float64Array, ay: Float64Array, i: number) {
  const s = Math.hypot(ax[i], ay[i]);
  if (s > PAD_MAX_SPEED) {
    ax[i] *= PAD_MAX_SPEED / s;
    ay[i] *= PAD_MAX_SPEED / s;
  }
}

/** Moves one body in a ripple or eat: a radial kick of PUSH_SPEED if it lies within reach of (x, y). */
function kick(
  px: number,
  py: number,
  vx: Float64Array,
  vy: Float64Array,
  i: number,
  x: number,
  y: number,
  reach: number,
) {
  const dx = px - x;
  const dy = py - y;
  const d = Math.hypot(dx, dy);
  if (d > reach) return;
  // A push at the exact centre goes along +x.
  const ux = d > 0 ? dx / d : 1;
  const uy = d > 0 ? dy / d : 0;
  vx[i] += ux * PUSH_SPEED;
  vy[i] += uy * PUSH_SPEED;
  capSpeed(vx, vy, i);
}

/**
 * A koi's wake on one body: within radius + r, the body takes WAKE_GAIN of the koi's velocity, plus the
 * same amount outward from the koi, scaled by the overlap. Its speed is then capped at PAD_MAX_SPEED.
 */
function nudge(
  px: number,
  py: number,
  r: number,
  x: number,
  y: number,
  vx: number,
  vy: number,
  radius: number,
  ax: Float64Array,
  ay: Float64Array,
  i: number,
) {
  const reach = radius + r;
  const dx = px - x;
  const dy = py - y;
  const d = Math.hypot(dx, dy);
  if (d >= reach) return;
  const gain = (WAKE_GAIN * (reach - d)) / reach;
  const speed = Math.hypot(vx, vy);
  const ux = d > 0 ? dx / d : 1;
  const uy = d > 0 ? dy / d : 0;
  ax[i] += (vx + ux * speed) * gain;
  ay[i] += (vy + uy * speed) * gain;
  capSpeed(ax, ay, i);
}

/** True when cell (col, row)'s centre lies outside the disc of radius rad centred at (cx, cy). */
function outsideDisc(
  col: number,
  row: number,
  cx: number,
  cy: number,
  rad: number,
  cw: number,
  ch: number,
) {
  const dx = (col + 0.5) * cw - cx;
  const dy = (row + 0.5) * ch - cy;
  return dx * dx + dy * dy > rad * rad;
}

/** Wraps a coordinate that has drifted past one edge back in from the other, by a body of radius R. */
function wrap(p: number, span: number, R: number) {
  if (p < -R) return p + span + 2 * R;
  if (p > span + R) return p - span - 2 * R;
  return p;
}

/**
 * The pond's floating plants, drawn over the water. Pads are opaque: each has a rim, a three-shade body,
 * veins on spokes, a centre `o`, and sometimes a water lily. Koi that cruise shallow push pads aside; deeper
 * koi pass underneath and are hidden. Duckweed drifts in patches and loose fronds on the same wind.
 *
 * Call layout() on resize, then per frame: pushFrom() per koi, step(), and drawShadows() and drawPlants() in
 * the render. ripples and eats call push().
 */
export class PondSurface {
  /** Pads in use. The arrays hold the most a canvas can take; the first padCount are live. */
  padCount = 0;
  padX = new Float64Array(0);
  padY = new Float64Array(0);
  padR = new Float64Array(0);
  /** Rotation and spin of each pad, rad and rad/s. */
  padRot = new Float64Array(0);
  padSpin = new Float64Array(0);
  /** Notch centreline, the lily's direction (opposite the notch), and the spokes' start angle and count. */
  padNotch = new Float64Array(0);
  padFlowerAng = new Float64Array(0);
  padSpokeBase = new Float64Array(0);
  padSpokeN = new Uint8Array(0);
  /** 1 when the pad carries a water lily; 1 when that lily is white (else pink). */
  padFlower = new Uint8Array(0);
  padFlowerWhite = new Uint8Array(0);
  /** Push velocity per pad, px/s. It decays, and the wind is added on top. */
  padVx = new Float64Array(0);
  padVy = new Float64Array(0);
  /** Duckweed patches in use: centres, radii and push velocities. */
  patchCount = 0;
  patchX = new Float64Array(0);
  patchY = new Float64Array(0);
  patchR = new Float64Array(0);
  patchVx = new Float64Array(0);
  patchVy = new Float64Array(0);
  /** Fronds in patches: the patch each belongs to, its offset from the centre, its glyph (0 `°`, 1 `·`) and its green (0 light, 1 dark). */
  frondCount = 0;
  frondPatch = new Uint8Array(0);
  frondDx = new Float32Array(0);
  frondDy = new Float32Array(0);
  frondGlyph = new Uint8Array(0);
  frondShade = new Uint8Array(0);
  /** Loose fronds that drift alone: position, push velocity, glyph and green. */
  looseCount = 0;
  looseX = new Float64Array(0);
  looseY = new Float64Array(0);
  looseVx = new Float64Array(0);
  looseVy = new Float64Array(0);
  looseGlyph = new Uint8Array(0);
  looseShade = new Uint8Array(0);

  private width = 0;
  private height = 0;
  private seed = 0;
  private cursor = 0;
  private windPhaseX = 0;
  private windPhaseY = 0;
  private shadowStyle = "";
  private bodyInnerStyle = "";
  private bodyMidStyle = "";
  private bodyOuterStyle = "";
  private rimStyle = "";
  private rimInkStyle = "";
  private veinStyle = "";
  private whiteStyle = "";
  private pinkStyle = "";
  private stamenStyle = "";
  private duckStyle = "";
  private duckDarkStyle = "";

  /** Converts the plant colours once. The shadow is black at a light alpha, so it reads on both pages. */
  setPalette(mode: "light" | "dark") {
    this.shadowStyle = `rgba(0,0,0,${SHADOW_ALPHA[mode]})`;
    this.bodyInnerStyle = css(BODY_INNER);
    this.bodyMidStyle = css(BODY_MID);
    this.bodyOuterStyle = css(BODY_OUTER);
    this.rimStyle = css(RIM);
    this.rimInkStyle = css(RIM_INK);
    this.veinStyle = css(VEIN_INK);
    this.whiteStyle = css(mode === "light" ? PETAL_WHITE_LIGHT : PETAL_WHITE);
    this.pinkStyle = css(PETAL_PINK);
    this.stamenStyle = css(STAMEN);
    this.duckStyle = css(DUCK);
    this.duckDarkStyle = css(DUCK_DARK);
  }

  /** Places the pads, water lilies and duckweed for a canvas of this size. bodyL is the largest koi's length in px. */
  layout(width: number, height: number, bodyL: number) {
    this.width = width;
    this.height = height;
    // An integer seed from the size, so a new size reseeds the draws.
    this.seed = (Math.round(width) * 73856093) ^ (Math.round(height) * 19349663) ^ SALT;
    this.cursor = 0;
    this.windPhaseX = this.rnd() * TAU;
    this.windPhaseY = this.rnd() * TAU;

    const want = clamp(Math.round((width * height) / PAD_AREA), PAD_MIN, PAD_MAX);
    this.padX = new Float64Array(want);
    this.padY = new Float64Array(want);
    this.padR = new Float64Array(want);
    this.padRot = new Float64Array(want);
    this.padSpin = new Float64Array(want);
    this.padNotch = new Float64Array(want);
    this.padFlowerAng = new Float64Array(want);
    this.padSpokeBase = new Float64Array(want);
    this.padSpokeN = new Uint8Array(want);
    this.padFlower = new Uint8Array(want);
    this.padFlowerWhite = new Uint8Array(want);
    this.padVx = new Float64Array(want);
    this.padVy = new Float64Array(want);
    this.padCount = 0;
    const coverLimit = PAD_COVER * width * height;
    let covered = 0;
    // Rejection: each pad gets PAD_TRIES tries to find a clear spot, then is left out. Stop once the cover is full.
    for (let i = 0; i < want && covered < coverLimit; i++) {
      for (let attempt = 0; attempt < PAD_TRIES; attempt++) {
        const r = (PAD_R_MIN + PAD_R_SPAN * this.rnd()) * bodyL;
        const u = this.rnd();
        const v = this.rnd();
        const lo = PAD_MARGIN * r;
        const spanX = width - 2 * lo;
        const spanY = height - 2 * lo;
        if (spanX < 0 || spanY < 0) continue;
        const x = lo + spanX * u;
        const y = lo + spanY * v;
        if (covered + Math.PI * r * r > coverLimit) break;
        if (this.overlapsPad(x, y, r)) continue;
        this.placePad(this.padCount++, x, y, r);
        covered += Math.PI * r * r;
        break;
      }
    }

    const patches = PATCH_MIN + Math.floor(this.rnd() * (PATCH_MAX - PATCH_MIN + 1));
    this.patchCount = patches;
    this.patchX = new Float64Array(PATCH_MAX);
    this.patchY = new Float64Array(PATCH_MAX);
    this.patchR = new Float64Array(PATCH_MAX);
    this.patchVx = new Float64Array(PATCH_MAX);
    this.patchVy = new Float64Array(PATCH_MAX);
    this.frondPatch = new Uint8Array(PATCH_MAX * FROND_MAX);
    this.frondDx = new Float32Array(PATCH_MAX * FROND_MAX);
    this.frondDy = new Float32Array(PATCH_MAX * FROND_MAX);
    this.frondGlyph = new Uint8Array(PATCH_MAX * FROND_MAX);
    this.frondShade = new Uint8Array(PATCH_MAX * FROND_MAX);
    this.frondCount = 0;
    for (let p = 0; p < patches; p++) {
      const R = (PATCH_R_MIN + PATCH_R_SPAN * this.rnd()) * bodyL;
      this.patchX[p] = this.rnd() * width;
      this.patchY[p] = this.rnd() * height;
      this.patchR[p] = R;
      const n = FROND_MIN + Math.floor(this.rnd() * (FROND_MAX - FROND_MIN + 1));
      for (let f = 0; f < n; f++) {
        const a = this.rnd() * TAU;
        // hash^1.5 pulls fronds toward the centre, so the patch is denser there.
        const d = Math.pow(this.rnd(), 1.5) * R;
        const k = this.frondCount++;
        this.frondPatch[k] = p;
        this.frondDx[k] = Math.cos(a) * d;
        this.frondDy[k] = Math.sin(a) * d;
        this.frondGlyph[k] = this.rnd() < 0.4 ? 1 : 0;
        this.frondShade[k] = this.rnd() < 0.5 ? 0 : 1;
      }
    }

    const loose = LOOSE_MIN + Math.floor(this.rnd() * (LOOSE_MAX - LOOSE_MIN + 1));
    this.looseCount = loose;
    this.looseX = new Float64Array(LOOSE_MAX);
    this.looseY = new Float64Array(LOOSE_MAX);
    this.looseVx = new Float64Array(LOOSE_MAX);
    this.looseVy = new Float64Array(LOOSE_MAX);
    this.looseGlyph = new Uint8Array(LOOSE_MAX);
    this.looseShade = new Uint8Array(LOOSE_MAX);
    for (let k = 0; k < loose; k++) {
      this.looseX[k] = this.rnd() * width;
      this.looseY[k] = this.rnd() * height;
      this.looseGlyph[k] = this.rnd() < 0.4 ? 1 : 0;
      this.looseShade[k] = this.rnd() < 0.5 ? 0 : 1;
    }
  }

  /** Advances the plants: the wind, pad spin, decaying pushes, pads pushed apart, and soft edges. */
  step(dt: number, t: number) {
    const { padX, padY, padR, padVx, padVy, width, height } = this;
    const n = this.padCount;
    const wx = WIND_X * Math.sin(WIND_X_RATE * t + this.windPhaseX);
    const wy = WIND_Y * Math.cos(WIND_Y_RATE * t + this.windPhaseY);
    const decay = Math.exp(-PUSH_DECAY * dt);
    for (let i = 0; i < n; i++) {
      this.padRot[i] += this.padSpin[i] * dt;
      padVx[i] *= decay;
      padVy[i] *= decay;
      padX[i] += (wx + padVx[i]) * dt;
      padY[i] += (wy + padVy[i]) * dt;
    }
    for (let i = 0; i < n; i++) {
      for (let j = i + 1; j < n; j++) {
        const dx = padX[j] - padX[i];
        const dy = padY[j] - padY[i];
        const d = Math.hypot(dx, dy);
        const min = padR[i] + padR[j];
        if (d >= min) continue;
        // Coincident centres split along x.
        const ux = d > 0 ? dx / d : 1;
        const uy = d > 0 ? dy / d : 0;
        const half = (min - d) / 2;
        padX[i] -= ux * half;
        padY[i] -= uy * half;
        padX[j] += ux * half;
        padY[j] += uy * half;
      }
    }
    for (let i = 0; i < n; i++) {
      const lo = PAD_MARGIN * padR[i];
      const hiX = width - lo;
      const hiY = height - lo;
      if (padX[i] < lo) padVx[i] += (lo - padX[i]) * EDGE_SPRING * dt;
      else if (padX[i] > hiX) padVx[i] -= (padX[i] - hiX) * EDGE_SPRING * dt;
      if (padY[i] < lo) padVy[i] += (lo - padY[i]) * EDGE_SPRING * dt;
      else if (padY[i] > hiY) padVy[i] -= (padY[i] - hiY) * EDGE_SPRING * dt;
      padX[i] = clamp(padX[i], lo, hiX);
      padY[i] = clamp(padY[i], lo, hiY);
    }

    // Duckweed rides the same wind, faster, and wraps around the edges.
    const { patchX, patchY, patchR, patchVx, patchVy } = this;
    for (let p = 0; p < this.patchCount; p++) {
      patchVx[p] *= decay;
      patchVy[p] *= decay;
      patchX[p] = wrap(patchX[p] + (DUCK_SPEED * wx + patchVx[p]) * dt, width, patchR[p]);
      patchY[p] = wrap(patchY[p] + (DUCK_SPEED * wy + patchVy[p]) * dt, height, patchR[p]);
    }
    const { looseX, looseY, looseVx, looseVy } = this;
    for (let k = 0; k < this.looseCount; k++) {
      looseVx[k] *= decay;
      looseVy[k] *= decay;
      looseX[k] = wrap(looseX[k] + (DUCK_SPEED * wx + looseVx[k]) * dt, width, 0);
      looseY[k] = wrap(looseY[k] + (DUCK_SPEED * wy + looseVy[k]) * dt, height, 0);
    }
  }

  /** A ripple set or an eat at (x, y): pads and patches within reach get a radial kick, capped in speed. */
  push(x: number, y: number, size: number) {
    const extra = PUSH_REACH_SIZE * size;
    for (let i = 0; i < this.padCount; i++) {
      kick(
        this.padX[i],
        this.padY[i],
        this.padVx,
        this.padVy,
        i,
        x,
        y,
        PUSH_REACH_R * this.padR[i] + extra,
      );
    }
    for (let p = 0; p < this.patchCount; p++) {
      kick(
        this.patchX[p],
        this.patchY[p],
        this.patchVx,
        this.patchVy,
        p,
        x,
        y,
        this.patchR[p] + extra,
      );
    }
  }

  /**
   * A koi's wake at (x, y), moving at (vx, vy) px/s, with the given radius: pads, patches and loose fronds within
   * reach are nudged along the koi's motion and outward from it. Called per koi, per frame.
   */
  pushFrom(x: number, y: number, vx: number, vy: number, radius: number) {
    for (let i = 0; i < this.padCount; i++) {
      nudge(
        this.padX[i],
        this.padY[i],
        this.padR[i],
        x,
        y,
        vx,
        vy,
        radius,
        this.padVx,
        this.padVy,
        i,
      );
    }
    for (let p = 0; p < this.patchCount; p++) {
      nudge(
        this.patchX[p],
        this.patchY[p],
        this.patchR[p],
        x,
        y,
        vx,
        vy,
        radius,
        this.patchVx,
        this.patchVy,
        p,
      );
    }
    for (let k = 0; k < this.looseCount; k++) {
      nudge(this.looseX[k], this.looseY[k], 0, x, y, vx, vy, radius, this.looseVx, this.looseVy, k);
    }
  }

  /** Shadows on the floor, under the creatures: each pad's disc, offset down and to the right. */
  drawShadows(g: CanvasRenderingContext2D, cw: number, ch: number, cols: number, rows: number) {
    g.fillStyle = this.shadowStyle;
    for (let i = 0; i < this.padCount; i++) {
      const rad = this.padR[i];
      const sx = this.padX[i] + SHADOW_DX * rad;
      const sy = this.padY[i] + SHADOW_DY * rad;
      const c0 = Math.max(0, Math.floor((sx - rad) / cw));
      const c1 = Math.min(cols - 1, Math.floor((sx + rad) / cw));
      const r0 = Math.max(0, Math.floor((sy - rad) / ch));
      const r1 = Math.min(rows - 1, Math.floor((sy + rad) / ch));
      for (let row = r0; row <= r1; row++) {
        const dy = (row + 0.5) * ch - sy;
        for (let col = c0; col <= c1; col++) {
          const dx = (col + 0.5) * cw - sx;
          if (dx * dx + dy * dy <= rad * rad) g.fillRect(col * cw, row * ch, cw, ch);
        }
      }
    }
  }

  /**
   * Pads, duckweed and then water lilies, drawn over the creatures. Every cell a pad covers is set in padMask,
   * so rings and duckweed skip it. koiMask marks cells held by a shallow koi: the pad leaves those cells alone,
   * so the koi shows on top. Lilies are drawn last, standing above the water.
   */
  drawPlants(
    g: CanvasRenderingContext2D,
    cw: number,
    ch: number,
    cols: number,
    rows: number,
    padMask: Uint8Array,
    koiMask: Uint8Array,
  ) {
    for (let i = 0; i < this.padCount; i++) {
      const cx = this.padX[i];
      const cy = this.padY[i];
      const rad = this.padR[i];
      const axis = this.padRot[i] + this.padNotch[i];
      const nx = Math.cos(axis);
      const ny = Math.sin(axis);
      const c0 = Math.max(0, Math.floor((cx - rad) / cw));
      const c1 = Math.min(cols - 1, Math.floor((cx + rad) / cw));
      const r0 = Math.max(0, Math.floor((cy - rad) / ch));
      const r1 = Math.min(rows - 1, Math.floor((cy + rad) / ch));
      // The cell holding the centre always counts as covered, so a tiny pad still shows.
      const ccol = Math.floor(cx / cw);
      const crow = Math.floor(cy / ch);
      for (let row = r0; row <= r1; row++) {
        for (let col = c0; col <= c1; col++) {
          const idx = row * cols + col;
          if (padMask[idx] || koiMask[idx]) continue;
          // Coverage: the sub-cell points inside the disc, minus the notch wedge.
          let hits = 0;
          for (let k = 0; k < SUB.length; k += 2) {
            const dx = (col + SUB[k]) * cw - cx;
            const dy = (row + SUB[k + 1]) * ch - cy;
            const d = Math.hypot(dx, dy);
            if (d > rad) continue;
            if (d > 0 && (dx * nx + dy * ny) / d >= NOTCH_COS) continue;
            hits++;
          }
          const centre = col === ccol && row === crow;
          if (hits === 0 && centre) hits = 1;
          if (hits === 0) continue;
          padMask[idx] = 1;
          const gx = col * cw + cw / 2;
          const gy = row * ch + ch / 2 + 1;
          const dx = (col + 0.5) * cw - cx;
          const dy = (row + 0.5) * ch - cy;
          const d = Math.hypot(dx, dy);
          // Rim: the outermost ring, 1 to 3 sub-cell hits, or a neighbour outside the disc.
          const rim = hits < 4 || this.touchesEdge(col, row, cx, cy, rad, cw, ch);
          if (rim) {
            g.fillStyle = this.rimStyle;
            g.fillRect(col * cw, row * ch, cw, ch);
            if (!centre) {
              g.fillStyle = this.rimInkStyle;
              g.fillText(hash3(col, row, SALT + 1) < 0.5 ? "." : "'", gx, gy);
            }
          } else {
            // Body: three radial shades with a hash jitter of one step, so the leaf is not flat.
            const t = d / rad;
            let s = t < INNER_EDGE ? 0 : t < MID_EDGE ? 1 : 2;
            s = clamp(s + Math.floor(hash3(col, row, SALT + 2) * 3) - 1, 0, 2);
            g.fillStyle =
              s === 0 ? this.bodyInnerStyle : s === 1 ? this.bodyMidStyle : this.bodyOuterStyle;
            g.fillRect(col * cw, row * ch, cw, ch);
            if (!centre && this.onSpoke(i, dx, dy, d, cw)) {
              g.fillStyle = this.veinStyle;
              g.fillText(veinGlyph(dx, dy), gx, gy);
            }
          }
          if (centre) {
            // The stem attaches at the centre.
            g.fillStyle = this.veinStyle;
            g.fillText("o", gx, gy);
          }
        }
      }
    }

    for (let f = 0; f < this.frondCount; f++) {
      const p = this.frondPatch[f];
      this.drawFrond(
        g,
        this.patchX[p] + this.frondDx[f],
        this.patchY[p] + this.frondDy[f],
        this.frondGlyph[f],
        this.frondShade[f],
        cw,
        ch,
        cols,
        rows,
        padMask,
      );
    }
    for (let k = 0; k < this.looseCount; k++) {
      this.drawFrond(
        g,
        this.looseX[k],
        this.looseY[k],
        this.looseGlyph[k],
        this.looseShade[k],
        cw,
        ch,
        cols,
        rows,
        padMask,
      );
    }

    for (let i = 0; i < this.padCount; i++) {
      if (!this.padFlower[i]) continue;
      const rad = this.padR[i];
      const fa = this.padRot[i] + this.padFlowerAng[i];
      const fc = Math.floor((this.padX[i] + Math.cos(fa) * FLOWER_REACH * rad) / cw);
      const fr = Math.floor((this.padY[i] + Math.sin(fa) * FLOWER_REACH * rad) / ch);
      const petal = this.padFlowerWhite[i] ? this.whiteStyle : this.pinkStyle;
      for (let dr = -1; dr <= 1; dr++) {
        for (let dc = -1; dc <= 1; dc++) {
          const col = fc + dc;
          const row = fr + dr;
          if (col < 0 || row < 0 || col >= cols || row >= rows) continue;
          const glyph = FLOWER_ROWS[dr + 1][dc + 1];
          g.fillStyle = glyph === "@" ? this.stamenStyle : petal;
          g.fillText(glyph, col * cw + cw / 2, row * ch + ch / 2 + 1);
        }
      }
    }
  }

  /** One frond: a single glyph in one of the two greens, unless a pad covers its cell. */
  private drawFrond(
    g: CanvasRenderingContext2D,
    x: number,
    y: number,
    glyph: number,
    shade: number,
    cw: number,
    ch: number,
    cols: number,
    rows: number,
    padMask: Uint8Array,
  ) {
    const col = Math.floor(x / cw);
    const row = Math.floor(y / ch);
    if (col < 0 || row < 0 || col >= cols || row >= rows) return;
    if (padMask[row * cols + col]) return;
    g.fillStyle = shade === 0 ? this.duckStyle : this.duckDarkStyle;
    g.fillText(glyph === 0 ? "°" : "·", col * cw + cw / 2, row * ch + ch / 2 + 1);
  }

  /** True when the cell's offset (dx, dy) from pad i's centre lies on one of its veins. */
  private onSpoke(i: number, dx: number, dy: number, d: number, cw: number) {
    if (d <= VEIN_INNER * this.padR[i]) return false;
    const n = this.padSpokeN[i];
    const step = TAU / n;
    const axis = this.padNotch[i];
    for (let k = 0; k < n; k++) {
      const a = this.padSpokeBase[i] + k * step;
      // Spokes near the notch are skipped, so the notch reads as a clean cut.
      if (Math.abs(Math.atan2(Math.sin(a - axis), Math.cos(a - axis))) < SPOKE_NOTCH_CLEAR)
        continue;
      // A ray from the centre: the cell must lie ahead of the centre along the spoke.
      if (dx * Math.cos(a) + dy * Math.sin(a) <= 0) continue;
      if (Math.abs(dx * Math.sin(a) - dy * Math.cos(a)) < VEIN_HALF * cw) return true;
    }
    return false;
  }

  /** True when one of the cell's four neighbours has its centre outside the pad's disc. */
  private touchesEdge(
    col: number,
    row: number,
    cx: number,
    cy: number,
    rad: number,
    cw: number,
    ch: number,
  ) {
    return (
      outsideDisc(col - 1, row, cx, cy, rad, cw, ch) ||
      outsideDisc(col + 1, row, cx, cy, rad, cw, ch) ||
      outsideDisc(col, row - 1, cx, cy, rad, cw, ch) ||
      outsideDisc(col, row + 1, cx, cy, rad, cw, ch)
    );
  }

  /** A seeded draw in [0, 1): the same canvas size always draws the same sequence. */
  private rnd() {
    return hash3(this.cursor++, this.seed, SALT);
  }

  private overlapsPad(x: number, y: number, r: number) {
    for (let j = 0; j < this.padCount; j++) {
      if (Math.hypot(x - this.padX[j], y - this.padY[j]) < r + this.padR[j]) return true;
    }
    return false;
  }

  private placePad(i: number, x: number, y: number, r: number) {
    this.padX[i] = x;
    this.padY[i] = y;
    this.padR[i] = r;
    this.padRot[i] = this.rnd() * TAU;
    this.padSpin[i] = (this.rnd() * 2 - 1) * PAD_SPIN;
    this.padNotch[i] = this.rnd() * TAU;
    // The lily sits on the far side of the notch, so the notch never covers it.
    this.padFlowerAng[i] = this.padNotch[i] + Math.PI;
    this.padSpokeBase[i] = this.rnd() * TAU;
    this.padSpokeN[i] = SPOKES_MIN + Math.floor(this.rnd() * (SPOKES_MAX - SPOKES_MIN + 1));
    this.padFlower[i] = this.rnd() < FLOWER_CHANCE ? 1 : 0;
    this.padFlowerWhite[i] = this.rnd() < FLOWER_WHITE_CHANCE ? 1 : 0;
    this.padVx[i] = 0;
    this.padVy[i] = 0;
  }
}

// Ported from https://github.com/stackedlol/ascii-sharks (used with the author's permission).
/**
 * Draws the World as a grid of ASCII cells:
 *   1. a cell grid on the page background, in the page's colours
 *   2. a wake field that diffuses where things swim, lighting the dots cyan
 *   3. fish as minimal ASCII dashes, one per cell, glinting on hard turns
 *   4. creatures rasterised cell-by-cell with supersampled edges: grey blocks
 *      shaded by the light, dense glyphs, and shimmering accent colours
 */
import { clamp, hash3, oklchToRgb, rgbToOklabL, smoothstep, TAU } from "./math";
import { CREATURE_IDS, CREATURES } from "./creatures";
import type {
  Coat,
  CreatureDef,
  OceanColors,
  OceanScene,
  PaintPoint,
  TailShape,
} from "./creatures/types";
import { Effects, type ParticleKind } from "./effects";
import { PondSurface } from "./pond";
import { FOAM_GLYPHS, GLINT_TICK, SeaSurface } from "./sea";
import { type Creature, SPINE_NODES, type World } from "./world";

export type OceanPalette = {
  /** Page background, opaque rgb 0–255. */
  background: [number, number, number];
  /** Page foreground (text colour), rgb 0–255. */
  foreground: [number, number, number];
  /** "light" when the background is light; greys are inverted so the scene reads as a negative. */
  mode: "light" | "dark";
};

/** Used until the engine reads the page theme: the original black-background look. */
export const DEFAULT_PALETTE: OceanPalette = {
  background: [0, 0, 0],
  foreground: [230, 238, 255],
  mode: "dark",
};

const ALPHA_LEVELS = 6;
const FISH_ALPHAS = [0.28, 0.42, 0.58, 0.74, 0.9];

// Dot colour classes: blue, green, red, pale; the last entry is the cyan wake.
const DOT_RGB: [number, number, number][] = [
